@push('scripts')<script>(function(){document.addEventListener('click',function(e){var edit=e.target.closest('.project-edit-toggle'),cancel=e.target.closest('.project-edit-cancel');if(edit){var actions=edit.closest('.inline-actions');edit.style.display='none';actions.querySelector('.project-edit-form').classList.add('is-open');}if(cancel){var actions=cancel.closest('.inline-actions');actions.querySelector('.project-edit-form').classList.remove('is-open');actions.querySelector('.project-edit-toggle').style.display='inline-block';}});})();</script>@endpush
